--- index.html
+++ index.html
@@ -16,9 +16,9 @@
 (()=>{'use strict';const canvas=document.getElementById('game'),ctx=canvas.getContext('2d'),$=id=>document.getElementById(id);let W=960,H=640,scale=1,raf=0,last=0,active=false,paused=false,gameOver=false,time=0,spawnTimer=0,toastTimer=0,levelTimer=0;
 const witch={x:480,y:320,r:14,hp:100,maxHp:100,xp:0,level:1,speed:195,faceX:1,faceY:0,invuln:0};let enemies=[],shots=[],particles=[],decor=[],kills=0,day=1,selected=0,keys={},joy={x:0,y:0},pointer={x:0,y:0,down:false},spellCooldown=0,castFlash=0;
 const spells=[{name:'Foxfire',icon:'✦',desc:'Quick homing ember',unlocked:true,cd:.42,dmg:24,speed:390,color:'#f5ba76',count:1},{name:'Moonbeam',icon:'☾',desc:'Piercing lunar shard',unlocked:false,cd:.72,dmg:36,speed:350,color:'#b9a2ff',count:1},{name:'Thorn burst',icon:'❋',desc:'Three wild thorns',unlocked:false,cd:1.05,dmg:22,speed:315,color:'#91dfa7',count:3}];
 function resize(){const r=canvas.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);canvas.width=Math.max(1,Math.floor(r.width*d));canvas.height=Math.max(1,Math.floor(r.height*d));scale=d;W=canvas.width;H=canvas.height;ctx.setTransform(1,0,0,1,0,0);seedDecor()}
-function seedDecor(){decor=[];let cols=Math.ceil(W/64),rows=Math.ceil(H/64);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let v=((x*89+y*173+x*y*11)%100);if(v<16)decor.push({x:x*64+20+(v%19),y:y*64+18+(v%29),type:v%3});}}
+function seedDecor(){decor=[];let cols=Math.ceil(W/scale/64),rows=Math.ceil(H/scale/64);for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){let v=((x*89+y*173+x*y*11)%100);if(v<16)decor.push({x:x*64+20+(v%19),y:y*64+18+(v%29),type:v%3});}}
 function ui(){ $('day').textContent=String(day).padStart(2,'0');$('kills').textContent=kills;$('hpText').textContent=`${Math.ceil(witch.hp)} / ${witch.maxHp}`;$('hpBar').style.width=`${Math.max(0,witch.hp/witch.maxHp*100)}%`;$('xpText').textContent=`${witch.xp} / ${xpNeed()}`;$('xpBar').style.width=`${witch.xp/xpNeed()*100}%`;$('spellCount').textContent=`${spells.filter(s=>s.unlocked).length} / 3`;renderSpellUI();$('questTitle').textContent=witch.level<5?'First light':'The old dark';$('questSub').textContent=witch.level<5?`Banish ${Math.max(0,5-kills%5)} creatures to progress`:'The Hollow is answering';$('objectiveText').textContent=witch.level<2?'The wisp-things are drawn to your light. Hold your ground and see what the forest teaches you.':witch.level<4?'The forest grows restless. Choose your spell and keep moving; the creatures are gathering.':'A deeper shadow stirs beyond the trees. Your magic is almost strong enough to face it.'}
 function renderSpellUI(){let list=$('spellList');list.innerHTML='';spells.forEach((s,i)=>{let row=document.createElement('div');row.className='spell-row'+(!s.unlocked?' locked':'')+(selected===i?' selected':'');row.innerHTML=`<div class="spell-icon">${s.icon}</div><div><div class="spell-name">${s.name}</div><div class="spell-desc">${s.unlocked?s.desc:`Unlock at level ${i+1}`}</div></div>${s.unlocked?'':`<span class="lock">⌑</span>`}`;row.onclick=()=>selectSpell(i);list.appendChild(row)});let m=$('mobileSpells');m.innerHTML='';spells.forEach((s,i)=>{if(!s.unlocked)return;let b=document.createElement('button');b.className='mobile-spell'+(selected===i?' selected':'');b.textContent=s.icon;b.setAttribute('aria-label',s.name);b.onclick=()=>selectSpell(i);m.appendChild(b)})}
 function selectSpell(i){if(!spells[i]?.unlocked)return;selected=i;renderSpellUI()}
 function xpNeed(){return 30+(witch.level-1)*18}
